css:
:root{
  --bg-page: #F6F6F4;
  --bg-card: #FFFFFF;
  --bg-field: #F1F1EF;
  --bg-inverse: #2E3134;
  --ink-1: #333638;
  --ink-2: #66696C;
  --ink-3: #A3A6A8;
  --line: #E4E4E1;
  --line-strong: #CFD0CC;
  --brand: #5E6D7C;
  --brand-deep: #445466;
  --brand-soft: #E6EBF0;
  --accent: #B08D85;
  --accent-soft: #F3E9E6;
  --ok: #567D68;
  --warn: #8F7A4E;
  --err: #A05F55;
  --font-head: "PingFang SC","HarmonyOS Sans SC","Source Han Sans SC","Noto Sans SC","Microsoft YaHei",system-ui,-apple-system,sans-serif;
  --font-body: "PingFang SC","HarmonyOS Sans SC","Source Han Sans SC","Noto Sans SC","Microsoft YaHei",system-ui,-apple-system,sans-serif;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --shadow-1: 0 1px 2px rgba(60,63,60,.06);
  --shadow-2: 0 12px 28px -18px rgba(60,63,60,.22);
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-card: 22px;
  --space-section: 120px;
  --dur: .28s;
  --ease: cubic-bezier(.25,.46,.45,.94);
}
